class Trellis2Native(Model):
    id = 'trellis2-native'
    genre = Genre.THREED
    label = 'TRELLIS.2 Native'
    description = 'Image to textured 3D mesh (native ComfyUI TRELLIS.2): background-removed conditioning → voxel structure → shape latent → texture atlas, saved as a .glb.'
    # Shared img-to-mesh form (2026-09-06): trellis2-native, pixal3d
    # and transfer_rig board ONE form tag so the card's Model dropdown
    # lists all three heads (the dropdown groups by form — one tag per
    # family rendered a single-option picker, i.e. no dropdown at all).
    form = 'form_img_to_mesh'
    engine = 'comfyui'
    card = 'img-to-mesh'
    # The studio-body claim: the trellis tenant (3d/img_to_mesh — the
    # glob id is the CARD DIR, underscores and all) runs the SHARED
    # generic AssemblyStudio (kind=assembly: slot rail + Stage
    # viewport — the Trellis/Anny "render the same" order), never a
    # second bespoke body. owns_params=False (the kimodo shape:
    # resolution/steps/cfg ride the shell); writes = the card's File
    # slots this family authors.
    studio = Studio(
        tenant='3d/img_to_mesh', owns_params=False,
        kind=StudioKind.ASSEMBLY,
        writes=(
            'input_image', 'rigged_glb', 'target_glb',
        ),
    )
    # the stock-stack weight set (see _TRELLIS2_PROVISIONS above)
    provisions = _TRELLIS2_PROVISIONS
    # FIVE loaders, one lane (cluster C): the int8 convrot unet (the
    # only weight provisioned/on disk — the bf16 cells are routes,
    # not artifacts), the shape vae (structure/mesh decodes), the
    # texture vae (atlas decode), dino_v3 (conditioning), birefnet
    # (background removal). Typed rows — the mask two-loader
    # precedent, extended for the two-VAE lane.
    lane_inputs = LaneInputs(
        unet='trellis_2_int8_convrot.safetensors',
        vae='trellis_2_shape_vae_bf16.safetensors',
        texture_vae='trellis_2_texture_vae_bf16.safetensors',
        clip_vision='dino_v3_L_naf_fp32.safetensors',
        background_removal='birefnet.safetensors',
    )
    defaults = dict(
            resolution=1024,
            bg_removal='auto',
            steps=12,
            cfg=7.5,
            shape_steps=20,
            shape_cfg=7.5,
            tex1_steps=12,
            tex1_cfg=7.5,
            tex2_steps=12,
            tex2_cfg=1.0,
            remesh_resolution=768,
            decimate_faces=700000,
            smooth_angle=180,
            atlas_size=4096,
            ao_size=1024,
            normal_size=2048,
            struct_sampler='euler',
            struct_scheduler='normal',
            shape_sampler='euler',
            shape_scheduler='normal',
            tex1_sampler='euler',
            tex1_scheduler='simple',
            tex2_sampler='euler',
            tex2_scheduler='normal',
            sd3_shift=5.0,
            rescale_struct=0.7,
            rescale_shape=0.5,
            override_struct=0.667,
            override_shape=0.769,
            seed=42,
            # NO filename_prefix (2026-09-07): the img-to-mesh surface
            # dropped the field (09-06 sweep); the run owns names now.
        )
    # the cascade as frozen rows (PYTHON SHAPE LAW rung 1)
    variants = (
        Variant(id='1024', label='1024', hint='Standard resolution — DEFAULT', route='trellis2-native', order=0, cells=(
                    Cell(quant='bf16', label='BF16', route='trellis2-native-bf16', vram_peak_gb=12.0),
                    Cell(quant='int8', label='INT8 ConvRot', route='trellis2-native-int8', vram_peak_gb=8.0),
        )),
        Variant(id='1536', label='1536', hint='Quality resolution — hero assets, final production', route='trellis2-native-1536', order=2, cells=(
                    Cell(quant='bf16', label='BF16', route='trellis2-native-1536-bf16', vram_peak_gb=16.0),
                    Cell(quant='int8', label='INT8 ConvRot', route='trellis2-native-1536-int8', vram_peak_gb=10.0),
        )),
        Variant(id='512', label='512', hint='Fast resolution — props, thumbnails, iteration', route='trellis2-native-512', order=1, cells=(
                    Cell(quant='bf16', label='BF16', route='trellis2-native-512-bf16', vram_peak_gb=8.0),
                    Cell(quant='int8', label='INT8 ConvRot', route='trellis2-native-512-int8', vram_peak_gb=5.0),
        )),
    )

    # the img-to-mesh card surface for the trellis arm (row 3,
    # 2026-09-06 — fifteenth card in the KnobRow migration, third
    # multi-arm). Thirty-one rows: the lift chain's four KSamplers
    # (structure .0 / shape .1 / texture .2+.3) plus the guide arms,
    # mesh, bake, and sampler-lab knobs. FAN-OUT rows target the
    # first twin and name the rest here (the ideogram width
    # precedent): seed → all four samplers; smooth_angle → both
    # smooth nodes; atlas_size → unwrap + voxel bake.
    # bg_removal is a branch directive (compile row). The pixal arm
    # mirrors this surface + camera_fov (shared _shared_lift_chain).
    card_knobs = (
        KnobRow(card='input_image', inject='LoadImage.0.image', kind='s'),
        KnobRow(card='seed', inject='KSampler.0.seed', kind='n'),
        KnobRow(card='resolution', inject='Trellis2UpsampleStage.0.target_resolution', kind='n'),
        KnobRow(card='steps', inject='KSampler.0.steps', kind='n'),
        KnobRow(card='cfg', inject='KSampler.0.cfg', kind='n'),
        KnobRow(card='bg_removal', inject='', kind='s'),
        KnobRow(card='shape_steps', inject='KSampler.1.steps', kind='n'),
        KnobRow(card='shape_cfg', inject='KSampler.1.cfg', kind='n'),
        KnobRow(card='tex1_steps', inject='KSampler.2.steps', kind='n'),
        KnobRow(card='tex1_cfg', inject='KSampler.2.cfg', kind='n'),
        KnobRow(card='tex2_steps', inject='KSampler.3.steps', kind='n'),
        KnobRow(card='tex2_cfg', inject='KSampler.3.cfg', kind='n'),
        KnobRow(card='remesh_resolution', inject='RemeshMesh.0.resolution', kind='n'),
        KnobRow(card='decimate_faces', inject='DecimateMesh.0.target_face_count', kind='n'),
        KnobRow(card='smooth_angle', inject='MeshSmoothNormals.0.crease_angle', kind='n'),
        KnobRow(card='atlas_size', inject='UnwrapMesh.0.resolution', kind='n'),
        KnobRow(card='ao_size', inject='BakeAmbientOcclusion.0.resolution', kind='n'),
        KnobRow(card='normal_size', inject='BakeNormalMapFromMesh.0.resolution', kind='n'),
        KnobRow(card='struct_sampler', inject='KSampler.0.sampler_name', kind='s'),
        KnobRow(card='struct_scheduler', inject='KSampler.0.scheduler', kind='s'),
        KnobRow(card='shape_sampler', inject='KSampler.1.sampler_name', kind='s'),
        KnobRow(card='shape_scheduler', inject='KSampler.1.scheduler', kind='s'),
        KnobRow(card='tex1_sampler', inject='KSampler.2.sampler_name', kind='s'),
        KnobRow(card='tex1_scheduler', inject='KSampler.2.scheduler', kind='s'),
        KnobRow(card='tex2_sampler', inject='KSampler.3.sampler_name', kind='s'),
        KnobRow(card='tex2_scheduler', inject='KSampler.3.scheduler', kind='s'),
        KnobRow(card='sd3_shift', inject='ModelSamplingSD3.0.shift', kind='n'),
        KnobRow(card='rescale_struct', inject='RescaleCFG.0.multiplier', kind='n'),
        KnobRow(card='rescale_shape', inject='RescaleCFG.1.multiplier', kind='n'),
        KnobRow(card='override_struct', inject='CFGOverride.0.start_percent', kind='n'),
        KnobRow(card='override_shape', inject='CFGOverride.1.start_percent', kind='n'),
    )

